func (s *sqliteStore) ListNotes(userID int64, opts ListNotesOptions) (*NotePage, error) {
	where := `n.user_id = ?`
	args := []any{userID}
	if tag := strings.ToLower(strings.TrimSpace(opts.Tag)); tag != "" {
		where += ` AND EXISTS (SELECT 1 FROM note_tags t WHERE t.note_id = n.id AND t.tag = ?)`
		args = append(args, tag)
	}
	if q := strings.TrimSpace(opts.Q); q != "" {
		where += ` AND (n.title LIKE '%' || ? || '%' ESCAPE '\' OR n.body LIKE '%' || ? || '%' ESCAPE '\')`
		like := escapeLike(q)
		args = append(args, like, like)
	}
	page := opts.Page
	if page < 1 {
		page = 1
	}
	size := opts.PageSize
	if size <= 0 {
		size = 20
	}

	total := 0
	if err := s.db.QueryRow(`SELECT count(*) FROM notes n WHERE `+where, args...).Scan(&total); err != nil {
		return nil, fmt.Errorf("store: count notes: %w", err)
	}
	rows, err := s.db.Query(`SELECT `+noteColumns+` FROM notes n WHERE `+where+`
		ORDER BY n.pinned DESC, n.updated_at DESC, n.id DESC LIMIT ? OFFSET ?`,
		append(args, size, (page-1)*size)...)
	if err != nil {
		return nil, fmt.Errorf("store: list notes: %w", err)
	}
	defer func() { _ = rows.Close() }()
	out := &NotePage{Total: total, Notes: []Note{}}
	for rows.Next() {
		n, err := s.scanNote(rows)
		if err != nil {
			return nil, fmt.Errorf("store: list notes: %w", err)
		}
		out.Notes = append(out.Notes, *n)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: list notes: %w", err)
	}
	for i := range out.Notes {
		tags, err := s.tagsOf(out.Notes[i].ID)
		if err != nil {
			return nil, err
		}
		out.Notes[i].Tags = tags
	}
	return out, nil
}

// escapeLike quotes the LIKE wildcards of a search term.
func escapeLike(s string) string {
	r := strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`)
	return r.Replace(s)
}

func (s *sqliteStore) CreateShare(noteID, userID int64, token string) (*Share, error) {
	res, err := s.exec(`INSERT INTO shares (note_id, user_id, token) VALUES (?, ?, ?)`, noteID, userID, token)
	if err != nil {
		return nil, err
	}
	id, err := res.LastInsertId()
	if err != nil {
		return nil, fmt.Errorf("store: share id: %w", err)
	}
	sh := &Share{Token: token, NoteID: noteID, UserID: userID, ID: id}
	var created string
	if err := s.db.QueryRow(`SELECT created_at FROM shares WHERE id = ?`, id).Scan(&created); err != nil {
		return nil, fmt.Errorf("store: get share: %w", err)
	}
	sh.CreatedAt = parseTime(created)
	return sh, nil
}

// GetShare answers the shared note for an active link; a revoked or unknown
// token, and a deleted note, are ErrNotFound.
func (s *sqliteStore) GetShare(token string) (*Note, error) {
	n, err := s.scanNote(s.db.QueryRow(`SELECT `+noteColumns+` FROM notes n
		JOIN shares h ON h.note_id = n.id
		WHERE h.token = ? AND h.revoked_at IS NULL`, token))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("store: get share: %w", err)
	}
	return n, nil
}

func (s *sqliteStore) RevokeShare(shareID, userID int64) error {
	res, err := s.exec(`UPDATE shares SET revoked_at = strftime('%Y-%m-%d %H:%M:%S','now')
		WHERE id = ? AND user_id = ? AND revoked_at IS NULL`, shareID, userID)
	if err != nil {
		return err
	}
	if n, err := res.RowsAffected(); err != nil {
		return fmt.Errorf("store: revoke: %w", err)
	} else if n == 0 {
		return ErrNotFound
	}
	return nil
}

func (s *sqliteStore) ListTags(userID int64) ([]TagCount, error) {
	rows, err := s.db.Query(`SELECT t.tag, count(*) FROM note_tags t
		JOIN notes n ON n.id = t.note_id
		WHERE n.user_id = ?
		GROUP BY t.tag ORDER BY t.tag`, userID)
	if err != nil {
		return nil, fmt.Errorf("store: list tags: %w", err)
	}
	defer func() { _ = rows.Close() }()
	out := []TagCount{}
	for rows.Next() {
		var tc TagCount
		if err := rows.Scan(&tc.Tag, &tc.Count); err != nil {
			return nil, fmt.Errorf("store: list tags: %w", err)
		}
		out = append(out, tc)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("store: list tags: %w", err)
	}
	return out, nil
}
